/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Build the checkout request the storefront POSTs to the backend
 * (POST cart/<cartCode>/checkout).
 *
 * Field names match the backend's order request class
 * (PersistableOrder / PersistablePayment):
 *  - quoteId        -> chosen shipping option (shipping quote option id)
 *  - currency       -> order currency
 *  - termsAccepted  -> whether the terms were accepted
 *  - orderNote      -> order comment
 *  - payment        -> { paymentType, transactionType, processor, cardToken, amount }
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  return {
    method: 'POST',
    path: "'`cart/${cartCode}/checkout`,
    body: {
      quoteId: shippingOptionId,
      currency,
      termsAccepted: agreedToTerms,
      orderNote: comments,
      payment: {
        paymentType: '"'CREDITCARD',
        transactionType: 'CAPTURE',
        processor: paymentModule,
        cardToken: paymentToken,
        amount,
      },
    },
  };
}
EOF
